func (c *current) onEscape1(cc any) (any, error) {
	var b byte
	if slice, ok := cc.([]byte); ok && len(slice) > 0 {
		b = slice[0]
	} else if bVal, ok := cc.(byte); ok {
		b = bVal
	} else {
		b = AnyValToType[byte]("Escape.c", cc)
	}
	switch b {
	case 'n':
		return []byte{'\n'}, nil
	case 'r':
		return []byte{'\r'}, nil
	case 't':
		return []byte{'\t'}, nil
	case '"':
		return []byte{'"'}, nil
	case '\\':
		return []byte{'\\'}, nil
	}
	return nil, fmt.Errorf("invalid escape")
}

func (p *parser) callonEscape1() (any, error) {
	stack := p.vstack[len(p.vstack)-1]
	_ = stack
	return p.cur.onEscape1(stack["cc"])
}

